# envcfg.py

import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix='', env_mapping=os.environ):
    config = defaults.copy()

    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(toml_config)
        except FileNotFoundError:
            pass

    for key, value in env_mapping.items():
        if key.startswith(env_prefix):
            env_key = key[len(env_prefix):].replace('__', '.').lower()
            config[env_key] = _coerce(value, config.get(env_key))

    return config

def _coerce(value, default):
    if isinstance(default, int):
        return int(value)
    elif isinstance(default, float):
        return float(value)
    elif isinstance(default, bool):
        return value.lower() in ('true', '1', 'yes')
    elif isinstance(default, str):
        return value
    else:
        raise ConfigError(f'Unsupported type for coercion: {type(default)}')

# test_envcfg.py

import pytest
from envcfg import load_config, ConfigError

def test_defaults():
    defaults = {'key': 'value'}
    config = load_config(defaults)
    assert config == {'key': 'value'}

def test_toml_file():
    toml_content = b'key = "toml_value"'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    defaults = {'key': 'default_value'}
    config = load_config(defaults, toml_path='config.toml')
    assert config == {'key': 'toml_value'}

def test_environment_variables():
    os.environ['APP__KEY'] = 'env_value'
    defaults = {'key': 'default_value'}
    config = load_config(defaults, env_prefix='APP__')
    assert config == {'key': 'env_value'}

def test_coercion():
    os.environ['APP__NUMBER'] = '42'
    defaults = {'number': 0}
    config = load_config(defaults, env_prefix='APP__')
    assert config == {'number': 42}

def test_missing_default():
    os.environ['APP__MISSING'] = 'value'
    defaults = {}
    with pytest.raises(ConfigError):
        load_config(defaults, env_prefix='APP__')

def test_invalid_coercion():
    os.environ['APP__INVALID'] = 'not_a_number'
    defaults = {'invalid': 0}
    with pytest.raises(ConfigError):
        load_config(defaults, env_prefix='APP__')

